  sec('22 · MARINE CYCLE AND COASTS', 'b'),
  t('<b>Marine erosion</b>', 'Waves aided by winds, currents, tides, storms; depends on wave size, slope, shore height, coast shape, rock, depth', 'Wave pressure compresses air in fissures → rupture; waves use debris as tools (corrasion); solvent action in limestone and chalk'),
  fl(['Cliff', 'Cave', 'Arch', 'Stack', 'Stump'], 'Cats Always Sit Still: C-A-S-S', 5),
  t('<b>Erosional features</b>', '<b>Chasm</b>: narrow, deep, headward erosion along vertical weakness; mouth widens → <b>bay</b>', '<b>Wave-cut platform</b>: sea cliffs retreat; <b>notch</b> at base (maximum erosion)', '<b>Sea cave</b> (differential erosion) → <b>sea arch</b>', '<b>Stack</b>: pillars offshore; further eroded (below low tide) → <b>stumps</b>', '<b>Blow/spouting hole</b>: air compressed in cave; noise; widen, walls collapse → <b>geo/gloup</b>'),
  t('<b>Depositional features</b>', '<b>Beach</b>: temporary debris cover on wave-cut platform', '<b>Bar</b>: submerged, offshore; encloses <b>lagoon</b>; <b>barrier</b> = overwater counterpart', '<b>Spit</b> (one end tied to headland) → <b>hook</b> (curved end)', '<b>Tombolo</b>: bar joining island', '<b>Marine dunes</b>: by wind, not waves'),
