  sec('24 · ARID CYCLE, LAKES, PLATEAUS', 'r'),
  mn('H-R-E', '<b>Hamada</b> = rocky (large smoothened rocks) · <b>Reg/Serir</b> = stony gravel and pebbles, easier to cross · <b>Erg/Koum</b> = sandy · <b>Cold deserts</b> (high altitude/latitude). H-R-E: Hard → Rubble → Ergs of sand'),
